#!/usr/bin/env python3
# THE DEUTERONOMY WALK 10b — THE DOCKET D1 (2026-09-20): the docket's five instruments DERIVED from 9b's forms by asserted substitutions (9b derived them from 8b's
# by sed): ch12_docket_common.py, ch12_docket_rows.py, ch12_docket_uncred.py, ch12_credit_survey.py, ch12_credit_carry.py. Departures from 9b's forms, each
# asserted: the cells' names (cold_run_place_name.py's six, the design's F1-F6); the chunk cap 27,000 → 76,000 bytes (one chunk = one Read under the cost
# rules' rule C — the Read tool's page holds ~90 KB, the shell's print ~30 KB); the carry's unresolved file named ch12_uncred_unres.txt (the chunk files run past
# _09 this chapter — the 9b name would collide). Run from the repo root.
import subprocess, os, re
ROOT = subprocess.check_output(['git', 'rev-parse', '--show-toplevel'], text=True).strip()
SP = os.path.dirname(os.path.abspath(__file__)); FORMS = f'{ROOT}/World/step9/forms_deuteronomy_walk'
def load(name): return open(f'{FORMS}/{name}', encoding='utf-8').read()
def sub(text, old, new, n=1):
    assert text.count(old) == n, (old[:60], text.count(old), n); return text.replace(old, new)
CELLS_OLD = "cold_run_blessing_and_curse.py (F1 the_discipline_retold, F2 the_land_watered_by_heaven, F3 the_second_paragraph, F4 the_borders_and_the_dread, F5 the_blessing_and_the_curse,\n# F6 the_readback)"
CELLS_NEW = "cold_run_place_name.py (F1 the_header_and_the_demolition, F2 the_place_chosen, F3 the_burnt_offerings_only_there, F4 the_profane_slaughter_the_blood_and_the_gates,\n# F5 the_border_enlarged_and_the_altar, F6 the_nations_cut_off_and_the_abomination — the design's six cells on the six claims' spans; the_readback the table)"
# 1 common
t = load('ch11_docket_common.py')
t = sub(t, "# THE DEUTERONOMY WALK 9b (8b's form by sed)", "# THE DEUTERONOMY WALK 10b (9b's form by derive_ch12_docket_tools.py)")
t = sub(t, CELLS_OLD, CELLS_NEW)
t = sub(t, "# 9b: the credited rows carried with their ledgers (ch11_credit_carry.py)", "# 10b: the credited rows carried with their ledgers (ch12_credit_carry.py — 9b's form)")
t = t.replace('ch11', 'ch12'); assert 'ch11' not in t and '9b' not in t.replace("9b's form", ''), [l for l in t.split('\n') if 'ch11' in l or '9b' in l]
open(f'{SP}/ch12_docket_common.py', 'w', encoding='utf-8').write(t)
# 2 rows
t = load('ch11_docket_rows.py'); t = t.replace('ch11', 'ch12'); assert t.count('ch12') == 1; open(f'{SP}/ch12_docket_rows.py', 'w', encoding='utf-8').write(t)
# 3 uncred (the cap raised)
t = load('ch11_docket_uncred.py')
t = sub(t, "# 9b docket — the UNCREDITED rows of the dump printed WHOLE (THE WHOLE-ROW RULE) into chunk files of at most 27,000 bytes each, in dump order; the chunk",
           "# 10b docket (9b's form) — the UNCREDITED rows of the dump printed WHOLE (THE WHOLE-ROW RULE) into chunk files of at most 76,000 bytes each (one chunk one Read —\n# the cost rules' rule C; 9b's cap was 27,000 for the shell's print), in dump order; the chunk")
t = sub(t, "CAP = 27000", "CAP = 76000\nSPLIT_AT = {582, 933}   # the docket runs' boundaries (D1 the rows before Avodah Zarah 45a:1; D2a Avodah Zarah and Chullin's five stretches before Bekhorot 15a:1 — the room left under the 600k cap after D1 took D2's first half; D2b the rest) — the dump's own order, the indexes computed at the derive: a chunk never spans two docket runs")
t = sub(t, "    if cur and cur_b + len(line.encode()) + 1 > CAP: flush()", "    if cur and (cur_b + len(line.encode()) + 1 > CAP or any(first < s <= i for s in SPLIT_AT)): flush()")   # the boundary row itself may be credited (skipped above) — the flush tests the boundary CROSSED, not hit (the second run's chunk 03 still spanned it)
t = t.replace('ch11', 'ch12'); assert 'ch11' not in t; open(f'{SP}/ch12_docket_uncred.py', 'w', encoding='utf-8').write(t)
# 4 survey
t = load('ch11_credit_survey.py'); t = sub(t, "# 9b docket — the credited addresses by ledger", "# 10b docket (9b's form) — the credited addresses by ledger")
t = t.replace('ch11', 'ch12'); assert 'ch11' not in t; open(f'{SP}/ch12_credit_survey.py', 'w', encoding='utf-8').write(t)
# 5 carry
t = load('ch11_credit_carry.py')
t = sub(t, "# 9b docket — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS (THE WHOLE-ROW RULE", "# 10b docket (9b's form) — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS (THE WHOLE-ROW RULE")   # the bare prefix stood twice (the header and the generated file's first line) — the first run fell here
t = sub(t, "# ch11_credited_rows.py (CREDITED_SPEC in dump order) and ch11_uncred_09.txt (the unresolved rows whole); prints the counts.",
           "# ch12_credited_rows.py (CREDITED_SPEC in dump order) and ch12_uncred_unres.txt (the unresolved rows whole — 9b's _09 name would collide with a chunk this chapter); prints the counts.")
t = sub(t, "out = ['# 9b docket — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS, generated by ch11_credit_carry.py (never typed)",
           "out = ['# 10b docket — THE CREDITED ROWS CARRIED WITH THEIR LEDGERS, generated by ch12_credit_carry.py (9b\\'s form; never typed)")
t = sub(t, "open(f'{SP}/ch11_uncred_09.txt', 'w', encoding='utf-8')", "open(f'{SP}/ch12_uncred_unres.txt', 'w', encoding='utf-8')")
t = sub(t, "n = n.replace('the halakha per R. Akiva', 'the halakha (the ruling) per R. Akiva')", "n = n.replace('the halakha per R. Akiva', 'the halakha (the ruling) per R. Akiva').replace(\"the folio's opening aggadah.\", \"the folio's opening aggadah (the lore).\")")   # a gloss on a carried word is display, inserted at the carry (9b's lesson) — the lint's one flag on the carried rows
t = t.replace('ch11', 'ch12'); assert 'ch11' not in t and 'uncred_09' not in t; open(f'{SP}/ch12_credit_carry.py', 'w', encoding='utf-8').write(t)
for f in ('ch12_docket_common.py', 'ch12_docket_rows.py', 'ch12_docket_uncred.py', 'ch12_credit_survey.py', 'ch12_credit_carry.py'):
    print('written', f, os.path.getsize(f'{SP}/{f}'), 'bytes')
